insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'ad8431d4-0165-5a30-ab75-67a400a236bb', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'A.1' limit 1), 'A.1 Kinematics · Lesson 1: Displacement, velocity, acceleration, motion graphs, suvat and projectiles', 'IB DP Physics · A.1 Kinematics', '/phys-a1-lesson1/', 'PHYS-A1-L1', 16, 1 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-A1-L1', 'A.1 Kinematics · Lesson 1: Displacement, velocity, acceleration, motion graphs, suvat and projectiles', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["400 m", "0 m", "5.0 m/s", "0 m/s"], "tip": "Displacement is from start to finish."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Gradient", "Area under the graph", "y-intercept"], "tip": "Gradient of v–t = a."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["3.0", "3 m"], ["96"]], "tips": ["a = Δv/t; s = (u + v)t/2."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["s = ½gt²", "½", "0.5", "45 = "], ["3.0", "3.03"]], "tips": ["s = ½gt²."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["0.50", "0.505", "t = "], ["horizontal", "12 ×", "constant"], ["6.0", "6.1"]], "tips": ["Find time from vertical motion."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["lower", "shorter", "range", "height"], ["asymmetric", "steeper", "not parabola", "descent"]], "tips": ["Height, range, shape."]}]}, "models": {"1": [["Q1", "Distance 400 m; displacement 0; average speed 400/80 = 5.0 m/s; average velocity 0."]], "2": [["Q2", "Gradient; area; y-intercept."]], "3": [["Q3", "a = 24 ÷ 8.0 = 3.0 m s⁻² [1]; s = (0 + 24) × 8.0 ÷ 2 = 96 m [1]."], ["Q4", "45 = ½ × 9.8 × t² [1], so t = √(90/9.8) = 3.0 s [1]."]], "4": [["Q5", "Vertical: 1.25 = ½ × 9.8 × t², t = 0.505 s [1]; horizontal velocity is constant [1]; distance = 12 × 0.505 = 6.1 m [1]."]], "5": [["Q6", "Air resistance reduces the maximum height and the range [1], and the path becomes asymmetric with a steeper descent than ascent [1]."]], "6": [["Exit ticket", "Displacement."]]}, "labels": {"q3_0": "Q3", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
