insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-A2-L1', 'A.2 Forces and momentum · Lesson 1: Newton''s laws, free-body diagrams, contact and field forces', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["First law", "Second law", "Third law", "Third law"], "tip": "Inertia, F = ma, pairs."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["2400"], ["2.0", "2 m"]], "tips": ["Resultant first."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Buoyancy", "Tension", "Weight", "Friction", "Normal force"], "tip": "One each."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["same body", "both act on the book", "one body"], ["different type", "gravitational", "contact", "earth"]], "tips": ["Which bodies? Which type?"]}]}, "models": {"1": [["Q1", "First; second; third; third."]], "2": [["Q2", "Resultant force = 3000 − 600 = 2400 N [1]; a = 2400 ÷ 1200 = 2.0 m s⁻² [1]."]], "3": [["Q3", "Buoyancy; tension; weight; friction; normal force."]], "4": [["Q4", "Both forces act on the same body (the book), whereas a third-law pair acts on different bodies [1]; they are also different types: weight is gravitational (its pair is the book pulling Earth) while the normal force is a contact force [1]."]], "6": [["Exit ticket", "The resultant force equals mass × acceleration (rate of change of momentum)."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '9ed7480e-1236-5fc5-acfa-35ceb4ae87cd', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'A.2' limit 1), 'A.2 Forces and momentum · Lesson 2: Momentum, impulse, collisions, explosions and circular motion', 'IB DP Physics · A.2 Forces and momentum', '/phys-a2-lesson2/', 'PHYS-A2-L2', 13, 12 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-A2-L2', 'A.2 Forces and momentum · Lesson 2: Momentum, impulse, collisions, explosions and circular motion', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["3.0", "3 n s", "3.0 n s"], ["30"]], "tips": ["Δp = mΔv."]}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["time", "longer"], ["force", "smaller", "less", "reduce"]], "tips": ["F = Δp/Δt."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["2.0 m", "2.0", "6.0 = 3"], ["9.0", "6.0 j"], ["3.0 j", "3 j"]], "tips": ["Momentum before = after."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["mv²/r", "16", "0.50 × 16"], ["10 n", "10"]], "tips": ["F = mv²/r."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["direction", "changing"], ["velocity", "vector", "towards the centre"]], "tips": ["Velocity is a vector."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["friction"], ["gravit"]], "tips": ["Name the real force."]}]}, "models": {"1": [["Q1", "Impulse = Δp = 0.15 × 20 = 3.0 N s [1]; F = 3.0 ÷ 0.10 = 30 N [1]."], ["Q2", "The airbag increases the time over which the person''s momentum changes [1]; for the same change in momentum, the average force is smaller (F = Δp/Δt) [1]."]], "2": [["Q3", "6.0 = 3.0v, v = 2.0 m s⁻¹ [1]; Ek before = ½ × 2 × 3² = 9.0 J, after = ½ × 3 × 2² = 6.0 J [1]; energy lost = 3.0 J [1]."]], "3": [["Q4", "F = mv²/r = 0.50 × 4.0² ÷ 0.80 [1] = 10 N [1]."], ["Q5", "Its direction is continuously changing [1], so its velocity (a vector) changes, which means it accelerates, towards the centre [1]."]], "4": [["Q6", "(a) Friction between the tyres and the road [1]; (b) the gravitational force of Earth on the Moon [1]."]], "6": [["Exit ticket", "Yes (in an isolated system); only kinetic energy is not conserved."]]}, "labels": {"q1_0": "Q1", "q1_1": "Q2", "q2_0": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
