insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-A3-L1', 'A.3 Work, energy and power · Lesson 1: Work, energy conservation, Sankey diagrams, power, efficiency and energy density', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["mgh", "98", "= ½mv²"], ["9.9"]], "tips": ["mgh = ½mv²."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["294 J", "73.5 W", "125 W", "59%"], "tip": "mgh, then ÷ time."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["volume", "space", "tank", "small"], ["range", "further", "more energy", "carry"]], "tips": ["Size of tank."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["cos 30", "cos30", "0.866"], ["173", "170"]], "tips": ["W = Fs cos θ."]}]}, "models": {"1": [["Q1", "Loss of GPE = 2.0 × 9.8 × 5.0 = 98 J = gain of KE [1]; v = √(2 × 98 ÷ 2.0) = 9.9 m s⁻¹ [1]."]], "2": [["Q2", "mgh = 10 × 9.8 × 3.0 = 294 J; 294/4.0 = 73.5 W; 500/4.0 = 125 W; 294/500 = 59%."]], "3": [["Q3", "A fuel with high energy density stores more energy in a given volume [1], so a vehicle can travel further without a large, heavy tank [1]."]], "4": [["Q4", "W = 40 × 5.0 × cos 30° [1] = 173 J [1]."]], "6": [["Exit ticket", "Efficiency = useful output energy (or power) ÷ total input energy (or power)."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '0c9d2e3e-2ee4-5042-bd4e-2c89545581b6', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'A.4' limit 1), 'A.4 Rigid body mechanics · Lesson 1 (HL): Torque, rotational equilibrium, angular motion, moment of inertia and angular momentum', 'IB DP Physics · A.4 Rigid body mechanics', '/phys-a4-lesson1/', 'PHYS-A4-L1', 11, 31 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-A4-L1', 'A.4 Rigid body mechanics · Lesson 1 (HL): Torque, rotational equilibrium, angular motion, moment of inertia and angular momentum', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["12"], ["6.0", "6 n"]], "tips": ["τ = Fr sin θ."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["4.0", "4 rad"], ["50"]], "tips": ["α = Δω/t."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 1, "pts": [["20"]], "tips": ["α = τ/I."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["moment of inertia", "smaller i", "mass closer"], ["rotational", "more translational", "less energy"]], "tips": ["Energy shared between translation and rotation."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["8.0", "iω", "conserved"], ["5.0", "5 rad"]], "tips": ["I₁ω₁ = I₂ω₂."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["l2/2i", "l²/2i", "i decreases", "smaller i"], ["work", "muscles", "energy from"]], "tips": ["E = L²/2I."]}]}, "models": {"1": [["Q1", "τ = 30 × 0.40 × sin 90° = 12 N m [1]; at 30°: 30 × 0.40 × sin 30° = 6.0 N m [1]."]], "2": [["Q2", "α = 20 ÷ 5.0 = 4.0 rad s⁻² [1]; θ = (0 + 20) × 5.0 ÷ 2 = 50 rad [1]."]], "3": [["Q3", "α = 6.0 ÷ 0.30 = 20 rad s⁻² [1]."], ["Q4", "The solid cylinder has a smaller moment of inertia because its mass is closer to the axis [1], so less of the gravitational energy becomes rotational KE and more becomes translational KE, giving a higher speed [1]."]], "4": [["Q5", "L = 4.0 × 2.0 = 8.0 kg m² s⁻¹, conserved [1]; ω = 8.0 ÷ 1.6 = 5.0 rad s⁻¹ [1]."]], "5": [["Q6", "E_k = L²/2I; L is constant and I decreases, so E_k increases [1]; the extra energy comes from the work done by her muscles pulling her arms in [1]."]], "6": [["Exit ticket", "τ = Iα."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd6d334f2-d732-5d57-8b29-06e60e4c68c2', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'A.5' limit 1), 'A.5 Galilean and special relativity · Lesson 1 (HL): Reference frames, postulates, Lorentz transformations, time dilation, length contraction and space–time diagrams', 'IB DP Physics · A.5 Galilean and special relativity', '/phys-a5-lesson1/', 'PHYS-A5-L1', 11, 41 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-A5-L1', 'A.5 Galilean and special relativity · Lesson 1 (HL): Reference frames, postulates, Lorentz transformations, time dilation, length contraction and space–time diagrams', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["40"], ["speed of light", "c", "same", "constant"]], "tips": ["Add velocities."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1.25", "1.67", "2.29", "1.00"], "tip": "γ = 1/√(1 − v²/c²)."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["22"], ["6.6", "6600", "6.57"]], "tips": ["Δt = γΔt₀; d = vt."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 1, "pts": [["26.6", "27", "26.57"]], "tips": ["tan θ = v/c."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["more muons", "reach the ground", "detected"], ["dilated", "longer lifetime", "γ", "earth frame"]], "tips": ["Expected vs observed."]}]}, "models": {"1": [["Q1", "40 m s⁻¹ relative to the ground [1]; for light this fails because the speed of light is measured as c by all inertial observers [1]."]], "2": [["Q2", "0.6c: 1.25; 0.8c: 1.67; 0.9c: 2.29; 0.01c: ≈ 1.00."]], "3": [["Q3", "Δt = 10 × 2.2 = 22 μs [1]; d = 0.995 × 3.0 × 10⁸ × 22 × 10⁻⁶ ≈ 6.6 km [1]."]], "4": [["Q4", "θ = tan⁻¹(0.5) = 26.6° [1]."]], "5": [["Q5", "Far more muons reach the ground than expected from their proper lifetime [1], because in Earth''s frame their lifetime is dilated by γ, so they survive long enough to travel the distance [1]."]], "6": [["Exit ticket", "The laws of physics are the same in all inertial frames; the speed of light in a vacuum is the same for all inertial observers."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
