insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-B2-L1', 'B.2 Greenhouse effect · Lesson 1: Energy balance, emissivity, albedo, the solar constant and greenhouse gases', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["340", "s/4"], ["238", "240"]], "tips": ["Divide by 4, then × (1 − α)."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["238", "σt⁴", "σt4", "5.67"], ["255"]], "tips": ["T⁴ = 238/σ."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["natural frequency", "vibrat", "bend", "stretch"], ["match", "resonance", "same frequency", "absorb"]], "tips": ["Frequency match."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["πr²", "πr2", "cross-section", "disc"], ["4πr²", "4πr2", "surface area", "sphere"]], "tips": ["Area intercepted vs total area."]}]}, "models": {"1": [["Q1", "Average incoming = 1360 ÷ 4 = 340 W m⁻² [1]; absorbed = 0.70 × 340 = 238 W m⁻² [1]."]], "2": [["Q2", "238 = 5.67 × 10⁻⁸ × T⁴ [1]; T = (4.2 × 10⁹)^¼ ≈ 255 K [1]."]], "3": [["Q3", "CO₂ molecules have natural frequencies of vibration (bending and stretching) in the infrared range [1]; IR radiation of the same frequency causes resonance, so energy is absorbed [1]."]], "4": [["Q4", "Earth intercepts sunlight over its cross-sectional area πR² [1], but this energy is spread over its whole surface area 4πR², so the average is S/4 [1]."]], "6": [["Exit ticket", "About 0.30."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '6d9cb69d-3751-5829-8a1f-dff2dd8728b0', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'B.3' limit 1), 'B.3 Gas laws · Lesson 1: Pressure, the mole, ideal gas laws, kinetic theory and internal energy', 'IB DP Physics · B.3 Gas laws', '/phys-b3-lesson1/', 'PHYS-B3-L1', 8, 71 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-B3-L1', 'B.3 Gas laws · Lesson 1: Pressure, the mole, ideal gas laws, kinetic theory and internal energy', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["p/t", "319/290", "200 × 319"], ["220"]], "tips": ["P₁/T₁ = P₂/T₂."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["faster", "kinetic energy", "speed"], ["more frequent", "frequency", "collide more"], ["momentum", "harder", "greater force"]], "tips": ["Speed, frequency, change in momentum."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 1, "pts": [["7.5 × 10", "7480", "7479", "7.48"]], "tips": ["U = 3/2 nRT."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["pv/kt", "n = pv"], ["6.0 × 10", "6.00 × 10", "6.0e23", "6 × 10"]], "tips": ["N = PV/kBT."]}]}, "models": {"1": [["Q1", "P₂ = 200 × 319 ÷ 290 [1] = 220 kPa [1]."]], "2": [["Q2", "Particles gain kinetic energy and move faster [1]; they collide with the walls more frequently [1]; each collision involves a larger change in momentum, so the force per unit area (pressure) increases [1]."]], "3": [["Q3", "U = 1.5 × 2.0 × 8.31 × 300 = 7.48 × 10³ J [1]."]], "4": [["Q4", "N = PV/(k_B T) = 100 000 × 0.024 ÷ (1.38 × 10⁻²³ × 290) [1] = 6.0 × 10²³ [1]."]], "6": [["Exit ticket", "PV = nRT and PV = NkBT."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '7778b838-d46d-5bc5-b519-1bdf7836bb55', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'B.4' limit 1), 'B.4 Thermodynamics · Lesson 1 (HL): First and second laws, entropy, gas processes, heat engines and the Carnot cycle', 'IB DP Physics · B.4 Thermodynamics', '/phys-b4-lesson1/', 'PHYS-B4-L1', 11, 81 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-B4-L1', 'B.4 Thermodynamics · Lesson 1 (HL): First and second laws, entropy, gas processes, heat engines and the Carnot cycle', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["200"], ["300"]], "tips": ["W = PΔV; ΔU = Q − W."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Adiabatic", "Isothermal", "Isovolumetric", "Isobaric"], "tip": "Which quantity is zero or constant?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 1, "pts": [["12.2", "12"]], "tips": ["ΔS = Q/T."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["0.625", "62.5", "63"], ["friction", "irreversible", "heat loss", "not ideal"]], "tips": ["1 − TC/TH."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["q = 0", "no heat", "adiabatic"], ["work done on", "δu", "internal energy increase"]], "tips": ["Apply the first law."]}]}, "models": {"1": [["Q1", "W = 100 000 × 2.0 × 10⁻³ = 200 J [1]; ΔU = 500 − 200 = 300 J [1]."]], "2": [["Q2", "Adiabatic: Q = 0; isothermal: ΔU = 0; isovolumetric: W = 0; isobaric: constant P."]], "3": [["Q3", "ΔS = 3340 ÷ 273 = 12.2 J K⁻¹ [1]."]], "4": [["Q4", "η = 1 − 300/800 = 0.625 (62.5%) [1]; real engines have friction, heat losses and irreversible processes, so efficiency is lower [1]."]], "5": [["Q5", "In an adiabatic process Q = 0 [1], so the work done on the gas increases its internal energy (ΔU = −W > 0), raising its temperature [1]."]], "6": [["Exit ticket", "η = 1 − TC/TH."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '0b5bda17-de47-5e39-b8bf-ab35b4edffc1', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'B.5' limit 1), 'B.5 Current and circuits · Lesson 1: Current, potential difference, resistance, resistivity, power, series and parallel circuits, emf and internal resistance', 'IB DP Physics · B.5 Current and circuits', '/phys-b5-lesson1/', 'PHYS-B5-L1', 11, 91 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-B5-L1', 'B.5 Current and circuits · Lesson 1: Current, potential difference, resistance, resistivity, power, series and parallel circuits, emf and internal resistance', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 1, "pts": [["0.034", "3.4 × 10"]], "tips": ["R = ρL/A."]}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["temperature", "hotter", "heat"], ["vibrat", "collisions", "ions"]], "tips": ["Heating and lattice ions."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["9.0 Ω", "2.0 Ω", "1.0 A", "6.0 A"], "tip": "Series add; parallel reciprocals."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["2.0 a", "2.0", "6.0/3.0"], ["5.0"]], "tips": ["I = ε/(R + r)."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["ldr+increase", "resistance increase", "more resistance"], ["decrease", "falls", "smaller share", "less"]], "tips": ["Share of the voltage."]}]}, "models": {"1": [["Q1", "R = 1.7 × 10⁻⁸ × 2.0 ÷ 1.0 × 10⁻⁶ = 0.034 Ω [1]."], ["Q2", "As current increases the filament heats up [1]; the lattice ions vibrate more, so electrons collide with them more often, increasing resistance [1]."]], "2": [["Q3", "9.0 Ω; 2.0 Ω; 9.0/9.0 = 1.0 A; 12/2.0 = 6.0 A."]], "3": [["Q4", "I = 6.0 ÷ (2.5 + 0.50) = 2.0 A [1]; V = 6.0 − 2.0 × 0.50 = 5.0 V [1]."]], "4": [["Q5", "As it gets darker, the LDR''s resistance increases [1], so it takes a larger share of the supply p.d. and the output across the fixed resistor decreases [1]."]], "6": [["Exit ticket", "P = IV = I²R = V²/R."]]}, "labels": {"q1_0": "Q1", "q1_1": "Q2", "q3_0": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '0d26e77d-cac9-529d-b613-4e4d37c33e83', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'C.1' limit 1), 'C.1 Simple harmonic motion · Lesson 1: Conditions for SHM, a = −ω²x, period of pendulums and springs, energy in oscillations', 'IB DP Physics · C.1 Simple harmonic motion', '/phys-c1-lesson1/', 'PHYS-C1-L1', 16, 101 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-C1-L1', 'C.1 Simple harmonic motion · Lesson 1: Conditions for SHM, a = −ω²x, period of pendulums and springs, energy in oscillations', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["2.0 Hz", "12.6 rad s⁻¹", "6.3 m s⁻²"], "tip": "ω = 2π/T; a_max = ω²x₀."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["proportional"], ["opposite", "towards equilibrium", "towards the equilibrium", "directed towards"]], "tips": ["Size and direction of acceleration."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["2.0 s", "0.99 m", "0.63 s", "4 times"], "tip": "T ∝ √l."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Maximum", "Zero", "Constant", "Zero", "Maximum"], "tip": "a = −ω²x."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["t = 2π", "√(l/g)", "inversely", "smaller g", "g decreases"], ["increase", "√6", "2.4", "longer"]], "tips": ["T = 2π√(l/g)."]}]}, "models": {"1": [["Q1", "f = 2.0 Hz; ω = 2π/0.50 = 12.6 rad s⁻¹; a_max = 12.6² × 0.040 = 6.3 m s⁻²."], ["Q2", "The acceleration (restoring force) is proportional to the displacement from equilibrium [1] and is always directed towards the equilibrium position (opposite to the displacement) [1]."]], "2": [["Q3", "T = 2π√(1/9.8) = 2.0 s; l = gT²/4π² = 0.99 m; T = 2π√(0.40/40) = 0.63 s; length ×4."]], "3": [["Q4", "Ek max at lowest point; speed zero at extremes; total constant; a zero at x = 0; a max at x = x₀."]], "4": [["Q5", "T = 2π√(l/g), so a smaller g gives a longer period [1]; the period increases by a factor of √6 ≈ 2.4 [1]."]], "6": [["Exit ticket", "a = −ω²x."]]}, "labels": {"q1_1": "Q2", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'fdc8b191-a44a-510b-b317-93ed5ce5d1f0', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'C.1' limit 1), 'C.1 Simple harmonic motion · Lesson 2 (HL): Phase angle and the equations of SHM', 'IB DP Physics · C.1 Simple harmonic motion', '/phys-c1-lesson2/', 'PHYS-C1-L2', 7, 102 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-C1-L2', 'C.1 Simple harmonic motion · Lesson 2 (HL): Phase angle and the equations of SHM', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["0.50 m s⁻¹", "0.40 m s⁻¹", "π rad"], "tip": "v = ω√(x₀² − x²)."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["½", "0.5 ×", "mω²x₀²", "0.5 × 0.20"], ["0.025", "2.5 × 10"]], "tips": ["E_T = ½mω²x₀²."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["x₀² − x²", "x0² - x²", "= x²", "x0^2 - x^2"], ["x² = x₀²/2", "x0²/2", "x₀/√2", "x0/√2"]], "tips": ["Set the two expressions equal."]}]}, "models": {"1": [["Q1", "v_max = 10 × 0.050 = 0.50 m s⁻¹; v = 10√(0.0025 − 0.0009) = 0.40 m s⁻¹; half a period = π."]], "2": [["Q2", "E_T = ½ × 0.20 × 5.0² × 0.10² [1] = 0.025 J [1]."]], "3": [["Q3", "½mω²(x₀² − x²) = ½mω²x² gives x₀² − x² = x² [1]; so x² = x₀²/2 and x = x₀/√2 [1]."]], "6": [["Exit ticket", "E_T = ½mω²x₀²."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '082f4bcc-e46b-5d77-b2a9-291c4efad678', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'C.2' limit 1), 'C.2 Wave model · Lesson 1: Transverse and longitudinal waves, wave equation, sound and electromagnetic waves', 'IB DP Physics · C.2 Wave model', '/phys-c2-lesson1/', 'PHYS-C2-L1', 13, 111 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-C2-L1', 'C.2 Wave model · Lesson 1: Transverse and longitudinal waves, wave equation, sound and electromagnetic waves', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Longitudinal", "Transverse", "Transverse", "Longitudinal", "Transverse"], "tip": "Direction of oscillation vs energy."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["0.75 m", "5.0 × 10¹⁴ Hz", "17 m", "1.7 cm"], "tip": "λ = v/f."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["longitudinal", "transverse"], ["medium", "vacuum", "speed", "faster"]], "tips": ["Type and medium."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["frequency+same", "frequency+unchanged", "frequency+constant"], ["wavelength+increase", "longer"]], "tips": ["v = fλ with f fixed."]}]}, "models": {"1": [["Q1", "Sound and P-waves: longitudinal. Light, ripples, S-waves: transverse."]], "2": [["Q2", "330/440 = 0.75 m; 3.0 × 10⁸/6.0 × 10⁻⁷ = 5.0 × 10¹⁴ Hz; 17 m; 1.7 cm."]], "3": [["Q3", "Sound is longitudinal whereas light is transverse [1]; sound needs a medium and cannot travel through a vacuum, while light can, at a much higher speed [1]."]], "4": [["Q4", "The frequency stays the same because it is set by the source [1]; since v increases and v = fλ, the wavelength increases [1]."]], "6": [["Exit ticket", "v = fλ."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'e038f943-5c38-58e8-b4a2-68b69178f8e1', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'C.3' limit 1), 'C.3 Wave phenomena · Lesson 1: Wavefronts, reflection, refraction, Snell''s law, diffraction, superposition and double-slit interference', 'IB DP Physics · C.3 Wave phenomena', '/phys-c3-lesson1/', 'PHYS-C3-L1', 16, 121 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-C3-L1', 'C.3 Wave phenomena · Lesson 1: Wavefronts, reflection, refraction, Snell''s law, diffraction, superposition and double-slit interference', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["19.5°", "41.8°", "2.00 × 10⁸ m s⁻¹", "Towards the normal"], "tip": "sin θ₂ = sin 30°/1.50."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["higher", "denser", "larger refractive"], ["greater than the critical", "exceed", "above the critical", "larger than the critical"]], "tips": ["Direction and angle."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Constructive", "Destructive", "Constructive", "Destructive"], "tip": "nλ or (n + ½)λ?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["4.0 mm", "Increases", "Increases", "Decreases"], "tip": "s = λD/d."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["path difference", "nλ", "whole number"], ["in phase", "constructive", "superpos"]], "tips": ["Path difference and superposition."]}]}, "models": {"1": [["Q1", "θ₂ = sin⁻¹(0.5/1.5) = 19.5°; θc = sin⁻¹(1/1.5) = 41.8°; v = 3.00 × 10⁸/1.50 = 2.00 × 10⁸ m s⁻¹; towards the normal."], ["Q2", "Light must travel from a medium of higher refractive index towards one of lower refractive index [1], with an angle of incidence greater than the critical angle [1]."]], "2": [["Q3", "4.0 = 2λ: constructive; 3.0 = 1.5λ: destructive; 0: constructive; 5.0 = 2.5λ: destructive."]], "3": [["Q4", "s = 600 × 10⁻⁹ × 2.0 ÷ 0.30 × 10⁻³ = 4.0 mm; red has longer λ: increases; smaller d: increases; smaller D: decreases."]], "4": [["Q5", "At a bright fringe the path difference from the two slits is a whole number of wavelengths (nλ) [1], so the waves arrive in phase and superpose constructively [1]."]], "6": [["Exit ticket", "n₁ sin θ₁ = n₂ sin θ₂."]]}, "labels": {"q1_1": "Q2", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
