insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-C3-L2', 'C.3 Wave phenomena · Lesson 2 (HL): Single-slit diffraction, modulated double-slit patterns and diffraction gratings', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["5.0 × 10⁻³ rad", "Wider", "Narrower"], "tip": "θ = λ/b."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["2.0 × 10⁻⁶ m", "17.5°", "36.9°", "3"], "tip": "d = 1/500 000 m."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["sharper", "narrower", "sharp"], ["brighter", "further apart", "wider spacing", "larger angles"]], "tips": ["Sharpness, brightness, spacing."]}]}, "models": {"1": [["Q1", "θ = 5.0 × 10⁻⁷/1.0 × 10⁻⁴ = 5.0 × 10⁻³ rad; narrower slit → wider; shorter λ → narrower."]], "2": [["Q2", "d = 2.0 × 10⁻⁶ m; θ₁ = sin⁻¹(0.30) = 17.5°; θ₂ = sin⁻¹(0.60) = 36.9°; n_max = 2.0 × 10⁻⁶/6.0 × 10⁻⁷ = 3.3 → 3."]], "3": [["Q3", "The grating maxima are much sharper (narrower) [1] and brighter, and more widely spaced, because many slits contribute and d is very small [1]."]], "6": [["Exit ticket", "nλ = d sin θ."]]}, "labels": {"q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '35098ed9-29cb-55fc-868c-5d7e335ec10b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'C.4' limit 1), 'C.4 Standing waves and resonance · Lesson 1: Standing waves on strings and in pipes, resonance and damping', 'IB DP Physics · C.4 Standing waves and resonance', '/phys-c4-lesson1/', 'PHYS-C4-L1', 16, 131 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-C4-L1', 'C.4 Standing waves and resonance · Lesson 1: Standing waves on strings and in pipes, resonance and damping', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Travelling wave", "Standing wave", "Travelling wave", "Standing wave"], "tip": "Energy transfer and amplitude."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["1.6 m", "200 Hz", "3.2 m", "100 Hz", "300 Hz"], "tip": "String/open: λ = 2L; closed: 4L, odd harmonics."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Light damping", "Critical damping", "Heavy damping"], "tip": "Oscillates? How fast?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["lower", "smaller", "reduced", "amplitude"], ["broader", "wider", "lower frequency", "flatter"]], "tips": ["Height and width of the peak."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["node", "closed end"], ["antinode", "open end", "4l", "quarter"]], "tips": ["Boundary conditions."]}]}, "models": {"1": [["Q1", "Energy transfer and equal amplitude: travelling. Nodes and in-phase segments: standing."]], "2": [["Q2", "String λ = 1.6 m, f = 200 Hz; closed pipe λ = 3.2 m, f = 100 Hz; next = 3rd harmonic 300 Hz."]], "3": [["Q3", "Light; critical; heavy."], ["Q4", "Increased damping lowers the maximum amplitude at resonance [1], and makes the peak broader, with the resonant frequency slightly lower [1]."]], "4": [["Q5", "There must be a node at the closed end and an antinode at the open end [1], so the length can only fit an odd number of quarter wavelengths (λ = 4L/n, n odd) [1]."]], "6": [["Exit ticket", "Half a wavelength."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f2f27f94-652b-526a-85f2-00fd616bb41b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'C.5' limit 1), 'C.5 Doppler effect · Lesson 1: The Doppler effect for sound and light, redshift and blueshift', 'IB DP Physics · C.5 Doppler effect', '/phys-c5-lesson1/', 'PHYS-C5-L1', 10, 141 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-C5-L1', 'C.5 Doppler effect · Lesson 1: The Doppler effect for sound and light, redshift and blueshift', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Higher", "Lower", "Higher", "Same"], "tip": "Wavefronts bunched or spread?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Redshift", "6.6 nm", "3.0 × 10⁶ m s⁻¹", "Away from us"], "tip": "v = cΔλ/λ."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["approach", "towards", "compressed", "closer together"], ["away", "spread", "longer wavelength", "lower frequency"]], "tips": ["Before and after."]}]}, "models": {"1": [["Q1", "Higher; lower; higher; same."]], "2": [["Q2", "Longer λ: redshift; Δλ = 6.6 nm; v = 3.0 × 10⁸ × 6.6/656.3 = 3.0 × 10⁶ m s⁻¹; moving away."]], "3": [["Q3", "As the car approaches, the wavefronts are compressed, so the observed wavelength is shorter and the frequency higher [1]; as it moves away, the wavefronts are spread out, giving a longer wavelength and lower frequency [1]."]], "6": [["Exit ticket", "It is moving away from us."]]}, "labels": {"q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '4c154903-4a01-56e1-b4a3-df4c2ec328f0', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'C.5' limit 1), 'C.5 Doppler effect · Lesson 2 (HL): Doppler equations for sound and mechanical waves', 'IB DP Physics · C.5 Doppler effect', '/phys-c5-lesson2/', 'PHYS-C5-L2', 5, 142 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-C5-L2', 'C.5 Doppler effect · Lesson 2 (HL): Doppler equations for sound and mechanical waves', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["877 Hz", "739 Hz", "847 Hz"], "tip": "Choose the signs carefully."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["340 + 40", "380", "v + u"], ["447", "450"]], "tips": ["Receding source: + in the denominator."]}]}, "models": {"1": [["Q1", "800 × 340/310 = 877 Hz; 800 × 340/368 = 739 Hz; 800 × 360/340 = 847 Hz."]], "2": [["Q2", "f′ = 500 × 340 ÷ (340 + 40) = 500 × 340/380 [1] = 447 Hz [1]."]], "6": [["Exit ticket", "Decreases."]]}, "labels": {"q2_0": "Q2", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
