insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-D1-L1', 'D.1 Gravitational fields · Lesson 1: Kepler''s laws, Newton''s law of gravitation, field strength and orbits', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["First law", "Second law", "Third law"], "tip": "Shape, speed, period."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["9.81 N kg⁻¹", "2.45 N kg⁻¹", "One quarter", "8.43 N kg⁻¹"], "tip": "g = GM/r²."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["gmm/r²", "gmm/r2", "mv²/r", "mv2/r"], ["2πr/t", "v = 2πr", "2pir/t"], ["4π²", "t² =", "t2 ="]], "tips": ["Equate forces; substitute v."]}, {"kind": "choice", "id": "q3_1", "q": "Q4", "max": 3, "n": 3, "ans": ["Decreases", "Increases", "Unchanged"], "tip": "v = √(GM/r)."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["force per unit mass", "force/mass", "force per kilogram"], ["small", "test mass", "point mass"]], "tips": ["Force per..."]}]}, "models": {"1": [["Q1", "First; second; third."]], "2": [["Q2", "9.81; 9.81/4 = 2.45; ¼; GM/(6.87 × 10⁶)² = 8.43 N kg⁻¹."]], "3": [["Q3", "Gravitational force provides centripetal force: GMm/r² = mv²/r [1]; substitute v = 2πr/T [1]; rearrange to T² = (4π²/GM) r³, so T² ∝ r³ [1]."], ["Q4", "Speed decreases; period increases; mass has no effect."]], "4": [["Q5", "The gravitational force per unit mass [1] experienced by a small point (test) mass placed at that point in the field [1]."]], "6": [["Exit ticket", "F = Gm₁m₂/r²."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '8343645c-7eb3-5481-8819-2950eb1dc522', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'D.1' limit 1), 'D.1 Gravitational fields · Lesson 2 (HL): Gravitational potential energy and potential, escape speed, orbital energy', 'IB DP Physics · D.1 Gravitational fields', '/phys-d1-lesson2/', 'PHYS-D1-L2', 12, 152 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-D1-L2', 'D.1 Gravitational fields · Lesson 2 (HL): Gravitational potential energy and potential, escape speed, orbital energy', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["−6.26 × 10⁷ J kg⁻¹", "−3.13 × 10⁷ J kg⁻¹", "3.13 × 10⁹ J", "Perpendicular"], "tip": "W = mΔV."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["2gm/r", "√(2", "2 × 3.99", "1.25 × 10"], ["11.2", "1.12 × 10⁴", "11 200", "1.12 x 10"]], "tips": ["v = √(2GM/R)."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Decreases", "Increases", "Increases", "Decreases"], "tip": "E_T = −GMm/2r."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["zero at infinity", "infinity", "infinite"], ["attractive", "work done by", "energy released", "less than zero"]], "tips": ["Reference point."]}]}, "models": {"1": [["Q1", "V = −GM/R = −6.26 × 10⁷; at 2R half: −3.13 × 10⁷; W = 100 × 3.13 × 10⁷ = 3.13 × 10⁹ J; perpendicular."]], "2": [["Q2", "v = √(2 × 3.99 × 10¹⁴ ÷ 6.37 × 10⁶) [1] = 1.12 × 10⁴ m s⁻¹ (11.2 km s⁻¹) [1]."]], "3": [["Q3", "Radius decreases; speed and Ek increase; total energy decreases (more negative)."]], "4": [["Q4", "Gravitational potential energy is defined as zero at infinite separation [1]; because gravity is attractive, work is done by the field (energy is released) as the masses come together, so Ep is less than zero [1]."]], "6": [["Exit ticket", "v_esc = √(2GM/r)."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b1d07b83-93b5-5f25-b40e-a4a276284bfe', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'D.2' limit 1), 'D.2 Electric and magnetic fields · Lesson 1: Charge, Coulomb''s law, electric field strength, field lines and magnetic fields', 'IB DP Physics · D.2 Electric and magnetic fields', '/phys-d2-lesson1/', 'PHYS-D2-L1', 13, 161 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-D2-L1', 'D.2 Electric and magnetic fields · Lesson 1: Charge, Coulomb''s law, electric field strength, field lines and magnetic fields', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["6.25 × 10¹⁸", "3.2 × 10⁻¹⁹ C", "Attract", "Electrons"], "tip": "n = Q/e."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["0.90 N", "1.8 × 10⁴ N C⁻¹", "5.0 × 10⁴ V m⁻¹", "8.0 × 10⁻¹⁵ N"], "tip": "F = kq₁q₂/r²; E = V/d; F = qE."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Concentric circles", "Parallel and uniform", "Like a bar magnet"], "tip": "Draw them."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["oil drop", "drops", "charge on"], ["multiple", "integer", "whole number", "1.6"]], "tips": ["What did all the charges have in common?"]}]}, "models": {"1": [["Q1", "1/1.6 × 10⁻¹⁹ = 6.25 × 10¹⁸; +3.2 × 10⁻¹⁹ C; attract; electrons."]], "2": [["Q2", "0.90 N; 8.99 × 10⁹ × 5 × 10⁻⁷/0.25 = 1.8 × 10⁴ N C⁻¹; 5.0 × 10⁴ V m⁻¹; 1.6 × 10⁻¹⁹ × 5 × 10⁴ = 8.0 × 10⁻¹⁵ N."]], "3": [["Q3", "Concentric circles; uniform inside; bar-magnet pattern outside."]], "4": [["Q4", "Millikan measured the charge on many charged oil drops by balancing them in an electric field [1]; every charge was a whole-number multiple of 1.6 × 10⁻¹⁹ C, showing charge comes in discrete units [1]."]], "6": [["Exit ticket", "F = kq₁q₂/r²."]]}, "labels": {"q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '5a65a539-5c34-566f-8f62-98145f6f77c8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'D.2' limit 1), 'D.2 Electric and magnetic fields · Lesson 2 (HL): Electric potential energy, potential, equipotentials and conducting spheres', 'IB DP Physics · D.2 Electric and magnetic fields', '/phys-d2-lesson2/', 'PHYS-D2-L2', 10, 162 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-D2-L2', 'D.2 Electric and magnetic fields · Lesson 2 (HL): Electric potential energy, potential, equipotentials and conducting spheres', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["9.0 × 10⁴ V", "0", "2.0 × 10⁻¹⁶ J", "1250 eV"], "tip": "V = kq/r; W = qΔV."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Zero", "Constant (equal to the surface value)", "Decreases as 1/r", "Decreases as 1/r²"], "tip": "Charge on the surface."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["same potential", "δv = 0", "no potential difference", "constant potential"], ["w = qδv", "w = qΔv", "zero", "perpendicular"]], "tips": ["W = qΔV."]}]}, "models": {"1": [["Q1", "9.0 × 10⁴ V; 0 (potentials cancel); 1.6 × 10⁻¹⁹ × 1250 = 2.0 × 10⁻¹⁶ J = 1250 eV."]], "2": [["Q2", "E inside zero; V inside constant; outside V ∝ 1/r and E ∝ 1/r²."]], "3": [["Q3", "All points on an equipotential are at the same potential, so ΔV = 0 [1]; since W = qΔV, the work done is zero (the force is perpendicular to the motion) [1]."]], "6": [["Exit ticket", "Zero."]]}, "labels": {"q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '5e0e1c36-abff-5bd5-8424-c9a68b911957', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'D.3' limit 1), 'D.3 Motion in electromagnetic fields · Lesson 1: Charged particles in electric and magnetic fields, forces on conductors', 'IB DP Physics · D.3 Motion in electromagnetic fields', '/phys-d3-lesson1/', 'PHYS-D3-L1', 12, 171 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-D3-L1', 'D.3 Motion in electromagnetic fields · Lesson 1: Charged particles in electric and magnetic fields, forces on conductors', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["qv", "½mv²", "3.2 × 10⁻¹⁶", "3.2e-16"], ["2.65 × 10⁷", "2.7 × 10⁷", "2.65e7"]], "tips": ["½mv² = qV."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1.6 × 10⁻¹³ N", "4.2 cm", "No change", "4.0 × 10⁵ m s⁻¹"], "tip": "r = mv/qB; v = E/B."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["0.30 N", "0", "2.0 × 10⁻⁴ N m⁻¹", "Attract"], "tip": "F = BIL sin θ; μ₀I₁I₂/2πr."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["perpendicular", "right angle"], ["centripetal", "constant speed", "constant magnitude", "circle"]], "tips": ["Direction and size of the force."]}]}, "models": {"1": [["Q1", "½mv² = qV = 1.6 × 10⁻¹⁹ × 2000 = 3.2 × 10⁻¹⁶ J [1]; v = √(2 × 3.2 × 10⁻¹⁶ ÷ 9.11 × 10⁻³¹) = 2.65 × 10⁷ m s⁻¹ [1]."]], "2": [["Q2", "F = 1.6 × 10⁻¹⁹ × 2 × 10⁶ × 0.5 = 1.6 × 10⁻¹³ N; r = 1.67 × 10⁻²⁷ × 2 × 10⁶/(1.6 × 10⁻¹⁹ × 0.5) = 0.042 m; speed unchanged; v = E/B = 4.0 × 10⁵."]], "3": [["Q3", "0.30 N; 0 (sin 0 = 0); 4π × 10⁻⁷ × 100/(2π × 0.10) = 2.0 × 10⁻⁴ N m⁻¹; attract."]], "4": [["Q4", "The magnetic force is always perpendicular to the velocity, so it changes direction but not speed [1]; it has constant magnitude and acts as a centripetal force, producing circular motion [1]."]], "6": [["Exit ticket", "r = mv/qB."]]}, "labels": {"q1_0": "Q1", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '0fe7f70f-7a9f-5e27-a0c1-5a3598cd57e1', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'D.4' limit 1), 'D.4 Induction · Lesson 1 (HL): Magnetic flux, Faraday''s and Lenz''s laws, induced emf and generators', 'IB DP Physics · D.4 Induction', '/phys-d4-lesson1/', 'PHYS-D4-L1', 11, 181 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-D4-L1', 'D.4 Induction · Lesson 1 (HL): Magnetic flux, Faraday''s and Lenz''s laws, induced emf and generators', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["5.0 × 10⁻³ Wb", "1.0 Wb", "5.0 V", "0.15 V"], "tip": "Φ = BA; ε = NΔΦ/Δt; ε = BvL."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["oppose", "opposing"], ["work", "energy", "otherwise", "create energy"]], "tips": ["What if it assisted the change?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Doubles", "Halves", "Unchanged"], "tip": "Rate of change of flux."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["rate of change", "changing fastest", "fastest"], ["cutting", "flux", "maximum rate"]], "tips": ["Faraday''s law."]}]}, "models": {"1": [["Q1", "Φ = 0.50 × 0.010 = 5.0 × 10⁻³ Wb; NΦ = 1.0 Wb; ε = 1.0/0.20 = 5.0 V; ε = 0.50 × 1.0 × 0.30 = 0.15 V."]], "2": [["Q2", "The induced current produces a force that opposes the motion causing it [1], so work must be done to keep the motion going, and this work becomes electrical energy; if it assisted the change, energy would be created from nothing [1]."]], "3": [["Q3", "Peak emf doubles; period halves; turns unchanged."]], "4": [["Q4", "Induced emf depends on the rate of change of flux linkage [1]; when the plane is parallel to B the flux is zero but changing at its fastest rate (the sides cut field lines perpendicularly), so the emf is maximum [1]."]], "6": [["Exit ticket", "The induced current flows in a direction that opposes the change that produced it."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b0ae4743-5523-534b-a473-66250967caf8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'E.1' limit 1), 'E.1 Structure of the atom · Lesson 1: Rutherford scattering, nuclear notation, atomic spectra and photons', 'IB DP Physics · E.1 Structure of the atom', '/phys-e1-lesson1/', 'PHYS-E1-L1', 9, 191 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-E1-L1', 'E.1 Structure of the atom · Lesson 1: Rutherford scattering, nuclear notation, atomic spectra and photons', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Atom is mostly empty space", "Nucleus is positively charged", "Nucleus is very small and dense"], "tip": "One each."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["3.0 × 10⁻¹⁹ J", "1.9 eV", "486 nm"], "tip": "E = hc/λ."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["continuous", "white light"], ["absorb", "specific", "photon"], ["dark lines", "missing", "re-emitted in all directions", "energy levels"]], "tips": ["Light through a cool gas."]}]}, "models": {"1": [["Q1", "Straight through → empty space; repelled → positive; few bounced back → small, dense."]], "2": [["Q2", "E = 6.63 × 10⁻³⁴ × 3 × 10⁸/6.63 × 10⁻⁷ = 3.0 × 10⁻¹⁹ J = 1.9 eV; λ = hc/E = 486 nm."]], "3": [["Q3", "Continuous (white) light passes through a cool gas [1]; atoms absorb photons whose energies exactly match the difference between energy levels [1]; these wavelengths are missing, appearing as dark lines (re-emitted light goes in all directions) [1]."]], "6": [["Exit ticket", "That the atom has a small, dense, positively charged nucleus."]]}, "labels": {"q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '541138ef-2ad3-538b-a10b-af8739668baa', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'E.1' limit 1), 'E.1 Structure of the atom · Lesson 2 (HL): Nuclear radius, closest approach and the Bohr model of hydrogen', 'IB DP Physics · E.1 Structure of the atom', '/phys-e1-lesson2/', 'PHYS-E1-L2', 11, 192 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-E1-L2', 'E.1 Structure of the atom · Lesson 2 (HL): Nuclear radius, closest approach and the Bohr model of hydrogen', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["7.0 × 10⁻¹⁵ m", "4.8 × 10⁻¹⁵ m", "4.6 × 10⁻¹⁴ m", "2"], "tip": "R₀A^(1/3); d = kQq/Ek."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["−3.40 eV", "−1.51 eV", "10.2 eV", "1.89 eV", "13.6 eV"], "tip": "E = −13.6/n²."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["close", "reach the nucleus", "within", "contact"], ["strong nuclear force", "strong force"]], "tips": ["Which force acts at very short range?"]}]}, "models": {"1": [["Q1", "1.2 × 10⁻¹⁵ × 208^(1/3) = 7.1 × 10⁻¹⁵ ≈ 7.0 × 10⁻¹⁵ m; 1.2 × 10⁻¹⁵ × 4 = 4.8 × 10⁻¹⁵ m; d = 8.99 × 10⁹ × 79 × 2 × (1.6 × 10⁻¹⁹)² ÷ (5 × 1.6 × 10⁻¹³) = 4.6 × 10⁻¹⁴ m; 8^(1/3) = 2."]], "2": [["Q2", "−3.40; −1.51; 10.2 eV; 1.89 eV (656 nm, red); 13.6 eV."]], "3": [["Q3", "High-energy alpha particles get close enough to reach the nucleus [1], where the strong nuclear force acts in addition to electrostatic repulsion, so Coulomb''s law alone no longer predicts the scattering [1]."]], "6": [["Exit ticket", "−13.6 eV."]]}, "labels": {"q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '06889956-e8c4-52dd-bd9e-4006d2266740', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'E.2' limit 1), 'E.2 Quantum physics · Lesson 1 (HL): Photoelectric effect, wave–particle duality, de Broglie wavelength and Compton scattering', 'IB DP Physics · E.2 Quantum physics', '/phys-e2-lesson1/', 'PHYS-E2-L1', 13, 201 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-E2-L1', 'E.2 Quantum physics · Lesson 1 (HL): Photoelectric effect, wave–particle duality, de Broglie wavelength and Compton scattering', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["0.8 eV", "0.8 V", "5.6 × 10¹⁴ Hz", "No change", "Increases"], "tip": "Ek = hf − Φ; f₀ = Φ/h."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["wave+any frequency", "intensity", "build up", "accumulate", "enough time"], ["photon", "one electron", "hf", "frequency"]], "tips": ["What does the wave model predict about dim light?"]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 3, "n": 3, "ans": ["7.3 × 10⁻¹¹ m", "1.1 × 10⁻³⁴ m", "Halves"], "tip": "λ = h/mv."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 1, "pts": [["2.43 × 10⁻¹²", "2.4 × 10⁻¹²", "2.43e-12", "2.43 pm"]], "tips": ["cos 90° = 0."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["diffraction", "rings", "pattern"], ["graphite", "crystal", "wavelength", "similar"]], "tips": ["What do waves do through gaps?"]}]}, "models": {"1": [["Q1", "0.8 eV; 0.8 V; f₀ = 2.3 × 1.6 × 10⁻¹⁹/6.63 × 10⁻³⁴ = 5.6 × 10¹⁴ Hz; Ek,max unchanged; more electrons."], ["Q2", "The wave model predicts that light of any frequency would eventually release electrons if intense enough or given enough time, as energy accumulates [1]; but each electron absorbs one photon of energy hf, so below f₀ no single photon has enough energy [1]."]], "2": [["Q3", "6.63 × 10⁻³⁴/(9.11 × 10⁻³¹ × 10⁷) = 7.3 × 10⁻¹¹ m; 6.63 × 10⁻³⁴/6 = 1.1 × 10⁻³⁴ m; halves."]], "3": [["Q4", "Δλ = 2.43 × 10⁻¹² × (1 − 0) = 2.43 × 10⁻¹² m [1]."]], "4": [["Q5", "Electrons fired through thin graphite form a diffraction pattern of rings on a screen [1]; diffraction is a wave property and occurs because the electron wavelength is similar to the spacing between atoms [1]."]], "6": [["Exit ticket", "E_k,max = hf − Φ."]]}, "labels": {"q1_1": "Q2", "q3_0": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '605c07d1-daf3-537a-8cb6-2dcb8a6019de', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'E.3' limit 1), 'E.3 Radioactive decay · Lesson 1: Binding energy, mass defect, decay types, equations, half-life and background radiation', 'IB DP Physics · E.3 Radioactive decay', '/phys-e3-lesson1/', 'PHYS-E3-L1', 15, 211 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-E3-L1', 'E.3 Radioactive decay · Lesson 1: Binding energy, mass defect, decay types, equations, half-life and background radiation', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["28.3", "28.32", "0.0304 × 931.5"], ["7.08", "7.1"]], "tips": ["× 931.5, ÷ 4."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Alpha", "¹⁴₇N", "Beta-plus", "²²²₈₆Rn", "Gamma"], "tip": "Balance A and Z."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["400 Bq", "100 Bq", "18 h", "1/16"], "tip": "Halve each half-life."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["60", "corrected"], ["30", "15 + 15"]], "tips": ["Subtract background, halve twice, add back."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["binding energy per nucleon", "binding energy"], ["increase", "higher", "iron", "more stable"]], "tips": ["Look at the curve."]}]}, "models": {"1": [["Q1", "Binding energy = 0.0304 × 931.5 = 28.3 MeV [1]; per nucleon = 28.3 ÷ 4 = 7.08 MeV [1]."]], "2": [["Q2", "Alpha; ¹⁴N; beta-plus; ²²²Rn; gamma."]], "3": [["Q3", "400 Bq; 18 h = 3 half-lives → 100 Bq; 18 h; 4 half-lives → 1/16."], ["Q4", "Corrected count rate = 75 − 15 = 60 per minute, which falls to 60 ÷ 4 = 15 after two half-lives [1]; the reading is 15 + 15 = 30 counts per minute [1]."]], "4": [["Q5", "In both processes the products have a higher binding energy per nucleon than the reactants [1], since they move towards the peak of the curve near iron, so energy is released [1]."]], "6": [["Exit ticket", "Alpha."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'afe732bf-9f68-58da-ad66-2c98634ea815', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'E.3' limit 1), 'E.3 Radioactive decay · Lesson 2 (HL): Stability, nuclear energy levels, neutrino evidence and the decay law', 'IB DP Physics · E.3 Radioactive decay', '/phys-e3-lesson2/', 'PHYS-E3-L2', 11, 212 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-E3-L2', 'E.3 Radioactive decay · Lesson 2 (HL): Stability, nuclear energy levels, neutrino evidence and the decay law', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Beta-minus", "Beta-plus", "Alpha"], "tip": "Move towards the stability line."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["continuous", "range"], ["shared", "third particle", "conservation", "missing energy"]], "tips": ["Why not a single energy?"]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["0.087 day⁻¹", "1.0 × 10⁻⁶ s⁻¹", "0.42", "4.2 × 10⁴ Bq"], "tip": "λ = ln2/T½; N/N₀ = e^(−λt)."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["n₀/2", "n0/2", "½ = e", "0.5 = e"], ["ln 2 = λ", "ln2 = λ", "λt½ = ln 2", "ln 2"]], "tips": ["Set N = N₀/2."]}]}, "models": {"1": [["Q1", "Neutron-rich: β⁻; proton-rich: β⁺; very heavy: α."], ["Q2", "Beta particles are emitted with a continuous range of energies, whereas the energy released is fixed [1]; so the energy must be shared with another, undetected particle (the neutrino) to conserve energy and momentum [1]."]], "2": [["Q3", "λ = 0.693/8.0 = 0.087 day⁻¹ = 1.0 × 10⁻⁶ s⁻¹; e^(−0.87) = 0.42; A = 1.0 × 10⁻⁶ × 4.2 × 10¹⁰ = 4.2 × 10⁴ Bq."]], "3": [["Q4", "At t = T½, N = N₀/2, so ½ = e^(−λT½) [1]; taking logs, ln 2 = λT½, so T½ = ln 2/λ [1]."]], "6": [["Exit ticket", "N = N₀e^(−λt)."]]}, "labels": {"q1_1": "Q2", "q3_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '7c6536d0-888d-51e0-aa53-ad47d5f4960a', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'E.4' limit 1), 'E.4 Fission · Lesson 1: Fission, chain reactions, nuclear reactors and nuclear waste', 'IB DP Physics · E.4 Fission', '/phys-e4-lesson1/', 'PHYS-E4-L1', 11, 221 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-E4-L1', 'E.4 Fission · Lesson 1: Fission, chain reactions, nuclear reactors and nuclear waste', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 2, "n": 2, "ans": ["36", "3"], "tip": "Balance A and Z."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Moderator", "Control rods", "Heat exchanger", "Shielding", "Fuel rods"], "tip": "One each."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["neutron-rich", "too many neutrons", "excess neutrons"], ["unstable", "beta", "decay"]], "tips": ["N/Z ratio."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["moderator+slow"], ["control+absorb"]], "tips": ["Slow vs absorb."]}]}, "models": {"1": [["Q1", "Z: 92 = 56 + 36; A: 236 = 144 + 89 + 3, so 3 neutrons."]], "2": [["Q2", "Moderator; control rods; heat exchanger; shielding; fuel rods."]], "3": [["Q3", "Fission products have too many neutrons for their size (they are neutron-rich) [1], so they are unstable and decay, usually by beta-minus emission [1]."]], "4": [["Q4", "The moderator slows neutrons down so they are more likely to cause fission [1]; control rods absorb neutrons to reduce or control the rate of reaction [1]."]], "6": [["Exit ticket", "Slow (thermal) neutrons are much more likely to be absorbed by U-235 and cause fission."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '804164be-f14e-51d5-ad99-5954e86d6e92', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Physics' and t.code = 'E.5' limit 1), 'E.5 Fusion and stars · Lesson 1: Stellar equilibrium, fusion, stellar evolution, HR diagrams, parallax and stellar radii', 'IB DP Physics · E.5 Fusion and stars', '/phys-e5-lesson1/', 'PHYS-E5-L1', 14, 231 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('PHYS-E5-L1', 'E.5 Fusion and stars · Lesson 1: Stellar equilibrium, fusion, stellar evolution, HR diagrams, parallax and stellar radii', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["repulsion", "repel", "positive"], ["kinetic energy", "fast", "close enough", "strong force"]], "tips": ["Positive nuclei."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["White dwarfs", "Supergiants", "Main sequence", "Red giants"], "tip": "Top right = big and cool; bottom left = small and hot."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["2.0 pc", "6.5 ly", "5800 K", "4 times"], "tip": "d = 1/p; λT = 2.9 × 10⁻³."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["r²", "√100", "proportional", "l ∝ r"], ["10"]], "tips": ["L ∝ R²T⁴."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["gravit", "inward"], ["radiation pressure", "outward", "fusion"]], "tips": ["Two forces."]}]}, "models": {"1": [["Q1", "Nuclei are positively charged and repel each other [1]; only at very high temperatures do they have enough kinetic energy to get close enough for the strong force to bind them [1]."]], "2": [["Q2", "White dwarfs; supergiants; main sequence; red giants."]], "3": [["Q3", "2.0 pc; 6.5 ly; 2.9 × 10⁻³/5 × 10⁻⁷ = 5800 K; R ∝ √L → 4."], ["Q4", "With equal T, L ∝ R², so R ∝ √L [1]; R_giant/R_Sun = √100 = 10 [1]."]], "4": [["Q5", "Inward gravitational force on the star''s material [1] is balanced by the outward radiation (and gas) pressure produced by fusion in the core [1]."]], "6": [["Exit ticket", "Its mass."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
